const trig = $('Telegram Trigger').item.json;
const sess = $json || {};
const msg = trig.message;
let chatId = null, userId = null, firstName = '', text = '';
if (msg) {
  chatId = msg.chat ? msg.chat.id : null;
  userId = msg.from ? msg.from.id : null;
  firstName = msg.from ? (msg.from.first_name || '') : '';
  text = msg.text || '';
}
const screen = sess['pantalla actual'] || '';
const cart = sess['carrito temporal'] || '[]';
const t = (text || '').trim();
const tl = t.toLowerCase();
let action = 'help';
let param = '';
const cats = { bebidas: 'Bebidas', bebida: 'Bebidas', comidas: 'Comidas', comida: 'Comidas', snacks: 'Snacks', snack: 'Snacks' };
if (tl.indexOf('/start') === 0 || tl === 'menu' || tl === 'inicio' || tl === 'hola' || tl === 'start') { action = 'start'; }
else if (tl.indexOf('/estado') === 0) { action = 'admin'; param = t.slice(7).trim(); }
else if (cats[tl]) { action = 'category'; param = cats[tl]; }
else if (tl === 'carrito' || tl === 'ver carrito' || tl === '/carrito') { action = 'cart'; }
else if (tl === 'confirmar' || tl === 'confirmo' || tl === '/confirmar') { action = 'confirm'; }
else if (tl === 'vaciar' || tl === 'vaciar carrito' || tl === '/vaciar') { action = 'clear'; }
else if (tl === 'pedidos' || tl === 'mis pedidos' || tl === '/pedidos') { action = 'status'; }
else if (tl === 'puntos' || tl === 'ver mis puntos' || tl === 'mis puntos' || tl === '/puntos') { action = 'puntos'; }
else if (/^\d+$/.test(t) && screen.indexOf('qty:') === 0) { action = 'setqty'; param = t; }
else if (/^\d+$/.test(t) && screen.indexOf('cat:') === 0) { action = 'pickproduct'; param = t; }
else if (t === '4') { action = 'puntos'; }
else { action = 'help'; }
return [{ json: { chatId: chatId, userId: String(userId), firstName: firstName || '', text: text, action: action, param: param, screen: screen, cart: cart } }];

const NL = String.fromCharCode(10);
const cat = $('Router').item.json.param;
const rows = $input.all().map(i => i.json).filter(r => String(r.categoria || "").toLowerCase() === String(cat || "").toLowerCase());
let lines = [cat, ''];
if (rows.length === 0) { lines.push('No hay productos en esta categoría.'); }
let idx = 1;
for (const r of rows) {
  const stock = Number(r.stock || 0);
  const avail = stock > 0 ? '' : ' (agotado)';
  lines.push(idx + '. ' + r.nombre + ' - $' + Number(r.precio || 0).toFixed(2) + avail);
  if (r.descripcion) lines.push('  ' + r.descripcion);
  idx++;
}
lines.push('');
lines.push('Escribe SOLO el número del producto que quieres elegir (ej: 1).');
lines.push('O escribe "menu" para volver al inicio, o "carrito" para ver tu carrito.');
return [{ json: { text: lines.join(NL), categoria: cat } }];

const NL = String.fromCharCode(10);
const r = $('Router').item.json;
const screen = r.screen || '';
const cat = screen.indexOf('cat:') === 0 ? screen.slice(4) : '';
const num = parseInt((r.param || '').trim(), 10);
const getId = (o) => o['id producto'] != null ? o['id producto'] : o.id_producto;
const menu = $input.all().map(i => i.json).filter(x => String(x.categoria || "").toLowerCase() === cat.toLowerCase());
let text, newScreen;
if (!cat || menu.length === 0) {
  text = 'Primero elige una categoría (Bebidas, Comidas, Snacks).';
  newScreen = 'home';
} else if (!num || num < 1 || num > menu.length) {
  text = 'Número de producto inválido. Escribe el número de un producto de la lista.';
  newScreen = screen;
} else {
  const p = menu[num - 1];
  const stock = Number(p.stock || 0);
  if (stock <= 0) {
    text = '"' + p.nombre + '" está agotado. Elige otro número de la lista.';
    newScreen = screen;
  } else {
    text = 'Elegiste: ' + p.nombre + ' ($' + Number(p.precio || 0).toFixed(2) + ')' + NL + NL + 'Ahora escribe la CANTIDAD que deseas (ej: 2).';
    newScreen = 'qty:' + getId(p) + '|' + p.nombre + '|' + Number(p.precio || 0) + '|' + stock;
  }
}
return [{ json: { text: text, screen: newScreen, cart: r.cart || '[]' } }];

const NL = String.fromCharCode(10);
const r = $('Router').item.json;
const screen = r.screen || '';
const payload = screen.indexOf('qty:') === 0 ? screen.slice(4) : '';
const parts = payload.split('|');
const idProd = parts[0] || '';
const nombreSess = parts[1] || '';
const precioSess = Number(parts[2] || 0);
const qty = parseInt((r.param || '').trim(), 10);
const getId = (o) => o['id producto'] != null ? o['id producto'] : o.id_producto;
const menu = $input.all().map(i => i.json);
const m = menu.find(x => String(getId(x)) === String(idProd));
const nombre = m ? m.nombre : nombreSess;
const precio = m ? Number(m.precio || 0) : precioSess;
const stock = m ? Number(m.stock || 0) : Number(parts[3] || 0);
let cart = [];
try { cart = JSON.parse(r.cart || '[]'); } catch (e) { cart = []; }
let text, newScreen;
if (!idProd) {
  text = 'Primero elige un producto. Escribe una categoría (Bebidas, Comidas, Snacks).';
  newScreen = 'home';
} else if (!qty || qty < 1) {
  text = 'Cantidad inválida. Escribe un número mayor a 0 (ej: 2).';
  newScreen = screen;
} else if (qty > stock) {
  text = 'Stock insuficiente de ' + nombre + '. Disponibles: ' + stock + '.' + NL + 'Escribe una cantidad menor o igual, o elige otro producto.';
  newScreen = screen;
} else {
  const existing = cart.find(c => String(c.id_producto) === String(idProd));
  if (existing) existing.cantidad = Number(existing.cantidad) + qty;
  else cart.push({ id_producto: idProd, nombre: nombre, precio: precio, cantidad: qty });
  let total = 0;
  for (const c of cart) total += Number(c.precio) * Number(c.cantidad);
  text = 'Agregado: ' + qty + ' x ' + nombre + NL + ' Total actual: $' + total.toFixed(2) + NL + NL + 'Escribe otra categoría para seguir comprando, "carrito" para verlo, o "confirmar" para finalizar.';
  newScreen = 'home';
}
return [{ json: { text: text, screen: newScreen, cart: JSON.stringify(cart) } }];

const NL = String.fromCharCode(10);
const r = $('Router').item.json;
let cart = [];
try { cart = JSON.parse(r.cart || '[]'); } catch (e) { cart = []; }
let lines = [' Tu carrito', ''];
let total = 0;
if (cart.length === 0) lines.push('Está vacío.');
for (const c of cart) {
  const sub = Number(c.precio) * Number(c.cantidad);
  total += sub;
  lines.push('• ' + c.cantidad + ' x ' + c.nombre + ' = $' + sub.toFixed(2));
}
lines.push('');
lines.push('Total: $' + total.toFixed(2));
lines.push('');
if (cart.length > 0) { lines.push('¿Deseas confirmar el pedido? Escribe "confirmar" para realizarlo o "vaciar" para borrarlo.'); }
else { lines.push('Escribe el nombre de una categoría (Bebidas, Comidas, Snacks) para agregar productos.'); }
return [{ json: { text: lines.join(NL) } }];

const NL = String.fromCharCode(10);
const r = $('Router').item.json;
let cart = [];
try { cart = JSON.parse(r.cart || '[]'); } catch (e) { cart = []; }
const getId = (o) => o['id producto'] != null ? o['id producto'] : o.id_producto;
const menu = $input.all().map(i => i.json);
const findM = (id) => menu.find(m => String(getId(m)) === String(id));
let ok = true;
let problems = [];
let total = 0;
if (cart.length === 0) { ok = false; problems.push('Tu carrito está vacío.'); }
for (const c of cart) {
  const m = findM(c.id_producto);
  const st = m ? Number(m.stock || 0) : 0;
  if (!m) { ok = false; problems.push('Producto no encontrado: ' + c.nombre); }
  else if (st < Number(c.cantidad)) { ok = false; problems.push('Sin stock suficiente de ' + c.nombre + ' (disponible ' + st + ').'); }
  total += Number(c.precio) * Number(c.cantidad);
}
const now = new Date();
const pad = (n) => String(n).padStart(2, "0");
const fecha = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
const hora = pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());
const idPedido = 'PED-' + now.getTime();
let detalleLines = [];
let menuUpdates = [];
for (const c of cart) {
  detalleLines.push(c.cantidad + ' x ' + c.nombre + ' ($' + Number(c.precio).toFixed(2) + ')');
  const m = findM(c.id_producto);
  if (m) menuUpdates.push({ id_producto: c.id_producto, nuevo_stock: Number(m.stock || 0) - Number(c.cantidad) });
}
const detalles = detalleLines.join(' | ');
return [{ json: { ok: ok, problems: problems.join(NL), id_pedido: idPedido, id_usuario: r.userId, chatId: r.chatId, detalles_pedido: detalles, total_pago: total.toFixed(2), estado: 'Recibido', fecha: fecha, hora: hora, menuUpdates: menuUpdates } }];

