const NL = String.fromCharCode(10);
const uid = $('Router').item.json.userId;
const getV = (o, snake, spaced) => o[snake] != null ? o[snake] : o[spaced];
const rows = $input.all().map(i => i.json).filter(r => String(getV(r, 'id_usuario', 'id usuario')) === String(uid));
rows.reverse();
let lines = ['Tus pedidos', ''];
if (rows.length === 0) lines.push('No tienes pedidos aún.');
for (const r of rows.slice(0, 5)) {
  lines.push('#' + getV(r, 'id_pedido', 'id pedido') + ' — ' + r.estado);
  lines.push('  ' + getV(r, 'detalles_pedido', 'detalles pedido'));
  lines.push('  Total: $' + getV(r, 'total_pago', 'total pago') + '  (' + r.fecha + ' ' + r.hora + ')');
  lines.push('');
}
lines.push('Escribe "menu" para hacer un nuevo pedido.');
return [{ json: { text: lines.join(NL) } }];

const r = $('Router').item.json;
const parts = (r.param || '').trim().split(/\s+/);
const idPedido = parts[0];
const nuevoEstado = parts.slice(1).join(' ');
const getV = (o, snake, spaced) => o[snake] != null ? o[snake] : o[spaced];
const rows = $input.all().map(i => i.json);
const p = rows.find(x => String(getV(x, 'id_pedido', 'id pedido')) === String(idPedido));
const ok = !!p && !!nuevoEstado;
return [{ json: { ok: ok, id_pedido: idPedido || '', estado: nuevoEstado, id_usuario: p ? getV(p, 'id_usuario', 'id usuario') : '', adminChat: r.chatId } }];

const uid = $('Router').item.json.userId;
const fnameRouter = $('Router').item.json.firstName || '';
const getV = (o, snake, spaced) => o[snake] != null ? o[snake] : o[spaced];
const rows = $input.all().map(i => i.json).filter(r => String(getV(r, 'id_telegram', 'id telegram')) === String(uid));
let nombre = fnameRouter;
let puntos = 0;
if (rows.length > 0) {
  const u = rows[0];
  const nom = getV(u, 'nombre_completo', 'nombre completo');
  if (nom) nombre = String(nom).split(' ')[0];
  puntos = Number(u.puntos || 0);
}
if (!nombre) nombre = 'cliente';
const text = 'Hola ' + nombre + ', actualmente tienes 🏆 ' + puntos + ' puntos acumulados. ¡Sigue comprando para canjear premios!';
return [{ json: { text: text } }];

const NL = String.fromCharCode(10);
const now = new Date();
const pad = (n) => String(n).padStart(2, "0");
const today = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
const getV = (o, snake, spaced) => o[snake] != null ? o[snake] : o[spaced];
const rows = $input.all().map(i => i.json).filter(r => String(r.fecha) === today);
let total = 0;
const count = rows.length;
const prod = {};
for (const r of rows) {
  total += Number(getV(r, 'total_pago', 'total pago') || 0);
  const det = String(getV(r, 'detalles_pedido', 'detalles pedido') || '');
  det.split('|').forEach(seg => {
    const m = seg.trim().match(/^(\d+)\s*x\s*(.+?)\s*\(/);
    if (m) { const q = parseInt(m[1], 10); const name = m[2].trim(); prod[name] = (prod[name] || 0) + q; }
  });
}
const top = Object.keys(prod).map(k => ({ name: k, qty: prod[k] })).sort((a, b) => b.qty - a.qty).slice(0, 5);
let lines = [' Reporte de ventas ' + today, '', ' Pedidos: ' + count, ' Ventas: $' + total.toFixed(2), '', ' Más vendidos:'];
if (top.length === 0) lines.push('Sin ventas hoy.');
for (const t of top) lines.push('• ' + t.name + ': ' + t.qty);
return [{ json: { text: lines.join(NL) } }];
